-- Go Getter 3, юнит 1 по рабочей тетради: домашки 3–7 (черновики)

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = '96161506-701b-4074-9115-ee113b71a739' and title = 'Homework 3';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('96161506-701b-4074-9115-ee113b71a739', 'Homework 3', 2, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 2, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_books.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 1 · Life at home</h2><p>Present Simple и Present Continuous: что происходит обычно, а что прямо сейчас.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'sort', $blk${"title": "Распредели выражения времени", "groups": [{"name": "Сейчас", "items": [{"text": "right now"}, {"text": "at the moment"}, {"text": "today"}]}, {"name": "Регулярно", "items": [{"text": "always"}, {"text": "often"}, {"text": "on Mondays"}, {"text": "at the weekend"}, {"text": "every week"}, {"text": "sometimes"}]}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'order', $blk${"title": "Расставь слова по порядку", "items": [{"words": ["She's", "dancing", "right", "now."], "sentence": "She's dancing right now."}, {"words": ["I'm", "working", "at", "home."], "sentence": "I'm working at home."}, {"words": ["Dad", "often", "drinks", "tea."], "sentence": "Dad often drinks tea."}, {"words": ["They", "play", "chess", "at", "the", "weekend."], "sentence": "They play chess at the weekend."}, {"words": ["We're", "doing", "our", "English", "homework", "now."], "sentence": "We're doing our English homework now."}, {"words": ["He", "gets", "up", "early", "every", "day."], "sentence": "He gets up early every day."}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай предложение и выбери, когда это происходит", "questions": [{"q": "She's dancing right now.", "type": "single", "correct": [0], "options": [{"text": "Сейчас"}, {"text": "Регулярно"}]}, {"q": "I'm working at home.", "type": "single", "correct": [0], "options": [{"text": "Сейчас"}, {"text": "Регулярно"}]}, {"q": "Dad often drinks tea.", "type": "single", "correct": [1], "options": [{"text": "Сейчас"}, {"text": "Регулярно"}]}, {"q": "They play chess at the weekend.", "type": "single", "correct": [1], "options": [{"text": "Сейчас"}, {"text": "Регулярно"}]}, {"q": "We're doing our English homework now.", "type": "single", "correct": [0], "options": [{"text": "Сейчас"}, {"text": "Регулярно"}]}, {"q": "He gets up early every day.", "type": "single", "correct": [1], "options": [{"text": "Сейчас"}, {"text": "Регулярно"}]}]}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "Соедини начало и конец предложения", "pairs": [{"left": "What are", "right": "you doing?"}, {"left": "Mum never", "right": "gets up late."}, {"left": "My teacher is", "right": "telling us a story."}, {"left": "We always", "right": "meet on Fridays."}, {"left": "Are they", "right": "playing basketball?"}, {"left": "I'm not going", "right": "to school."}]}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Выбери правильную форму глагола", "questions": [{"q": "Doctor Q ___ in his lab all day, every day.", "type": "single", "correct": [0], "options": [{"text": "works"}, {"text": "is working"}]}, {"q": "He usually ___ at eight o’clock in the morning.", "type": "single", "correct": [1], "options": [{"text": "is starting"}, {"text": "starts"}]}, {"q": "But today Doctor Q ___ his time outside the garage.", "type": "single", "correct": [1], "options": [{"text": "spends"}, {"text": "is spending"}]}, {"q": "Right now Pi and Doctor Q ___!", "type": "single", "correct": [1], "options": [{"text": "skateboard"}, {"text": "are skateboarding"}]}, {"q": "Millie is surprised because Doctor Q never ___.", "type": "single", "correct": [0], "options": [{"text": "skateboards"}, {"text": "is skateboarding"}]}, {"q": "Doctor Q isn’t all right. He ___ to bed now.", "type": "single", "correct": [1], "options": [{"text": "goes"}, {"text": "is going"}]}]}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай блог Фреда и выбери правильную форму глагола", "mode": "choice", "text": "This is George. He often __goes__ to the park. He usually __hangs out__ with his friends, Peter and Jess. They usually __ride__ their bikes.\nBut today George __isn't riding__ his bike. He __is skateboarding__ with Peter and Jess at a skatepark.\n— Hi, George! __Are you having__ fun?\n— Yes! I __am learning__ some new jumps. It isn't easy!", "choices": [["is going", "go"], ["is hanging out", "hang out"], ["are riding", "rides"], ["doesn't ride", "isn't ride"], ["skateboards", "skateboard"], ["Do you have", "Are you have"], ["learn", "is learning"]]}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'task', $blk${"title": "Ответь за Джорджа ✍️", "needs_review": true, "html": "<p>Джордж из блога отвечает на вопросы. Напиши его ответы — по предложению на каждый вопрос.</p><p>1 Where do you usually hang out with your friends?<br>2 What do you do there?<br>3 Where are you meeting Peter and Jess today?<br>4 What are you doing now?<br>5 Are you having fun?</p><p><i>Например: I usually hang out at the sports centre.</i></p>"}$blk$::jsonb, 7);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_medal.webp\" alt=\"\" style=\"height:200px\"></p><p>Дальше — как попросить о помощи и предложить свою.</p>"}$blk$::jsonb, 8);
end $$;

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = '96161506-701b-4074-9115-ee113b71a739' and title = 'Homework 4';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('96161506-701b-4074-9115-ee113b71a739', 'Homework 4', 3, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 3, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_highfive.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 1 · Life at home</h2><p>Как попросить о помощи, как предложить её и что ответить.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/gg3%20wb/GG%20L3%20WkBk%20A2.mp3", "html": "<h3>Asking for help</h3><p>Can you help me <i>with the sofa</i>, please?<br>Can you move <i>the coffee table</i>, please?</p><h3>Reacting</h3><p>No problem. / Yes, of course.<br>I’m sorry, I can’t. I’m busy right now.</p><h3>Offering help</h3><p>Can I help you <i>with the lamp</i>?<br>Do you need any help <i>with the lamp</i>?</p><h3>Reacting</h3><p>Yes, please. / No, that’s fine, thank you.</p><p>Послушай запись и повтори фразы вслух.</p>"}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай разговор и перетащи слова в пропуски", "mode": "drag", "text": "Mum: Can you __help__ me with the living room, please?\nBob: Yes, __of course__, Mum.\nMum: __Can__ you clear the table, Dan?\nDan: __No__ problem, Mum.\nBob: Do you __need__ any help with the bedrooms?\nMum: Yes, __please__. We can make the beds next.\nDan: Can I help you __with__ the car? I like washing the car!\nMum: No, that's __fine__, thank you. The car is clean."}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Выбери подходящий ответ", "questions": [{"q": "Мама просит: «Can you help me with the table, please?» Ты согласен.", "type": "single", "correct": [1], "options": [{"text": "Yes, please."}, {"text": "Yes, of course."}, {"text": "No, that’s fine, thank you."}]}, {"q": "Сестра предлагает: «Can I help you with your homework?» Помощь нужна.", "type": "single", "correct": [0], "options": [{"text": "Yes, please."}, {"text": "No problem."}, {"text": "I’m sorry, I can’t."}]}, {"q": "Друг просит помочь, но ты сейчас занят.", "type": "single", "correct": [2], "options": [{"text": "No, that’s fine, thank you."}, {"text": "Yes, please."}, {"text": "I’m sorry, I can’t. I’m busy right now."}]}, {"q": "Бабушка предлагает помощь, но она не нужна.", "type": "single", "correct": [1], "options": [{"text": "No problem."}, {"text": "No, that’s fine, thank you."}, {"text": "Yes, of course."}]}]}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'order', $blk${"title": "Расставь слова по порядку", "items": [{"words": ["Do", "you", "need", "any", "help", "with", "the", "shopping?"], "sentence": "Do you need any help with the shopping?", "prompt": "вопрос"}, {"words": ["No,", "that's", "fine,", "thank", "you."], "sentence": "No, that's fine, thank you.", "prompt": "ответ"}, {"words": ["Can", "you", "help", "me", "with", "the", "washing,", "please?"], "sentence": "Can you help me with the washing, please?", "prompt": "вопрос"}, {"words": ["I'm", "sorry,", "I", "can't.", "I'm", "busy", "right", "now."], "sentence": "I'm sorry, I can't. I'm busy right now.", "prompt": "ответ"}]}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Впиши по одному слову", "mode": "type", "text": "__Do__ you need any help with the sofa?\nCan you move the table, __please__?\nCan __you__ help me with the dishes?"}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'speaking', $blk${"title": "Разыграй разговор 🎤", "needs_review": true, "html": "<p>Дома генеральная уборка. Попроси кого-то о помощи, а потом предложи свою. Скажи четыре реплики: просьба — ответ — предложение помощи — ответ.</p><p><i>Например: Can you help me with the window, please?</i></p>"}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_trophy.webp\" alt=\"\" style=\"height:200px\"></p><p>Дальше — текст о характере.</p>"}$blk$::jsonb, 7);
end $$;

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = '96161506-701b-4074-9115-ee113b71a739' and title = 'Homework 5';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('96161506-701b-4074-9115-ee113b71a739', 'Homework 5', 4, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 4, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_girl_wave.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 1 · Life at home</h2><p>Читаем тест о характере и разбираем слова, которыми описывают людей.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<h3>Do my personality quiz!</h3><p><b>1 Your friend wants to see a cartoon at the cinema on Monday. You …</b><br>A go and have fun.<br>B do your homework first and then go.<br>C don’t go because you don’t like cartoons.</p><p><b>2 Your mum asks you to tidy your room. You …</b><br>A tidy it and listen to music.<br>B don’t tidy it. It’s always tidy!<br>C don’t tidy it. You like it messy.</p><p><b>3 You are at a café. Your friends are late. You …</b><br>A wait and play games on your phone.<br>B send them lots of texts.<br>C don’t wait and ask for a lemonade.</p><p><b>4 You want to listen to music. You …</b><br>A play it on speakers and dance around the room.<br>B listen on headphones in your bedroom.<br>C listen in the kitchen and tell your family to listen too.</p><p><b>Mostly A</b> — You are easy-going and patient. Sometimes you are loud.<br><b>Mostly B</b> — You are organised and tidy. You are usually easy-going.<br><b>Mostly C</b> — You are bossy and a bit messy. You like having fun.</p>"}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Перетащи слова в пропуски", "mode": "drag", "text": "John is __bossy__. He tells everybody what to do.\nThe kids make a lot of noise. They are __loud__.\nI'm __messy__. There are clothes on the floor and books on the bed.\nThe teacher is __patient__. He waits for all the students to finish.\nDad is __organised__. He uploads his photos to his tablet every day.\nSusan is __quiet__. She never makes a noise.\nAunt Jane is an __easy-going__ person. She doesn't tell us what to do or when to do it.\nThe twins always put away their clothes and toys. They're __tidy__ children."}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Выбери лучший заголовок для теста", "material": "<h3>Do my personality quiz!</h3><p><b>1 Your friend wants to see a cartoon at the cinema on Monday. You …</b><br>A go and have fun.<br>B do your homework first and then go.<br>C don’t go because you don’t like cartoons.</p><p><b>2 Your mum asks you to tidy your room. You …</b><br>A tidy it and listen to music.<br>B don’t tidy it. It’s always tidy!<br>C don’t tidy it. You like it messy.</p><p><b>3 You are at a café. Your friends are late. You …</b><br>A wait and play games on your phone.<br>B send them lots of texts.<br>C don’t wait and ask for a lemonade.</p><p><b>4 You want to listen to music. You …</b><br>A play it on speakers and dance around the room.<br>B listen on headphones in your bedroom.<br>C listen in the kitchen and tell your family to listen too.</p><p><b>Mostly A</b> — You are easy-going and patient. Sometimes you are loud.<br><b>Mostly B</b> — You are organised and tidy. You are usually easy-going.<br><b>Mostly C</b> — You are bossy and a bit messy. You like having fun.</p>", "questions": [{"q": "", "type": "single", "correct": [1], "options": [{"text": "What do you like?"}, {"text": "What are you like?"}, {"text": "What are you doing?"}]}]}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай тест ещё раз. Верно или неверно?", "material": "<h3>Do my personality quiz!</h3><p><b>1 Your friend wants to see a cartoon at the cinema on Monday. You …</b><br>A go and have fun.<br>B do your homework first and then go.<br>C don’t go because you don’t like cartoons.</p><p><b>2 Your mum asks you to tidy your room. You …</b><br>A tidy it and listen to music.<br>B don’t tidy it. It’s always tidy!<br>C don’t tidy it. You like it messy.</p><p><b>3 You are at a café. Your friends are late. You …</b><br>A wait and play games on your phone.<br>B send them lots of texts.<br>C don’t wait and ask for a lemonade.</p><p><b>4 You want to listen to music. You …</b><br>A play it on speakers and dance around the room.<br>B listen on headphones in your bedroom.<br>C listen in the kitchen and tell your family to listen too.</p><p><b>Mostly A</b> — You are easy-going and patient. Sometimes you are loud.<br><b>Mostly B</b> — You are organised and tidy. You are usually easy-going.<br><b>Mostly C</b> — You are bossy and a bit messy. You like having fun.</p>", "questions": [{"q": "The quiz tells you about your personality.", "type": "single", "correct": [0], "options": [{"text": "Верно"}, {"text": "Неверно"}]}, {"q": "Question 1 is about seeing a film.", "type": "single", "correct": [0], "options": [{"text": "Верно"}, {"text": "Неверно"}]}, {"q": "Question 2 is about chores.", "type": "single", "correct": [0], "options": [{"text": "Верно"}, {"text": "Неверно"}]}, {"q": "Question 3 is about shopping.", "type": "single", "correct": [1], "options": [{"text": "Верно"}, {"text": "Неверно"}]}, {"q": "In question 1, one answer is about a drink.", "type": "single", "correct": [1], "options": [{"text": "Верно"}, {"text": "Неверно"}]}, {"q": "In question 2, one answer is about homework.", "type": "single", "correct": [1], "options": [{"text": "Верно"}, {"text": "Неверно"}]}, {"q": "In question 3, two answers are about phones.", "type": "single", "correct": [0], "options": [{"text": "Верно"}, {"text": "Неверно"}]}, {"q": "There are four results.", "type": "single", "correct": [1], "options": [{"text": "Верно"}, {"text": "Неверно"}]}]}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай комментарии и выбери правильный вариант", "questions": [{"q": "Dave: I ___ your quiz! It’s great! I am mostly C and yes, I am bossy!", "type": "single", "correct": [0], "options": [{"text": "love"}, {"text": "hate"}]}, {"q": "Charlie: I ___ with your quiz! It isn’t right. I am mostly A. But I’m not loud! I’m quiet!", "type": "single", "correct": [1], "options": [{"text": "agree"}, {"text": "don’t agree"}]}, {"q": "Anita: I ___ with everything! I am mostly B and it’s true, I am tidy and easy-going.", "type": "single", "correct": [0], "options": [{"text": "agree"}, {"text": "don’t agree"}]}]}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'task', $blk${"title": "Пройди тест и напиши свой комментарий ✍️", "needs_review": true, "material": "<h3>Do my personality quiz!</h3><p><b>1 Your friend wants to see a cartoon at the cinema on Monday. You …</b><br>A go and have fun.<br>B do your homework first and then go.<br>C don’t go because you don’t like cartoons.</p><p><b>2 Your mum asks you to tidy your room. You …</b><br>A tidy it and listen to music.<br>B don’t tidy it. It’s always tidy!<br>C don’t tidy it. You like it messy.</p><p><b>3 You are at a café. Your friends are late. You …</b><br>A wait and play games on your phone.<br>B send them lots of texts.<br>C don’t wait and ask for a lemonade.</p><p><b>4 You want to listen to music. You …</b><br>A play it on speakers and dance around the room.<br>B listen on headphones in your bedroom.<br>C listen in the kitchen and tell your family to listen too.</p><p><b>Mostly A</b> — You are easy-going and patient. Sometimes you are loud.<br><b>Mostly B</b> — You are organised and tidy. You are usually easy-going.<br><b>Mostly C</b> — You are bossy and a bit messy. You like having fun.</p>", "html": "<p>Выбери ответы A, B или C и посмотри результат. Напиши три предложения: согласен ты с тестом или нет, какая у тебя буква и какой ты на самом деле.</p><p><i>Например: I don’t agree with the quiz. It isn’t right.</i></p>"}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_popper.webp\" alt=\"\" style=\"height:200px\"></p><p>Дальше — задание на слух и письмо.</p>"}$blk$::jsonb, 7);
end $$;

do $$
