begin
  select id into v_lesson from classroom_lessons
   where unit_id = '96161506-701b-4074-9115-ee113b71a739' and title = 'Homework 6';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('96161506-701b-4074-9115-ee113b71a739', 'Homework 6', 5, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 5, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_laptop.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 1 · Life at home</h2><p>Слушаем, кто какие дела делает по дому, и пишем о знакомом человеке.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Посмотри на картинку и выбери подпись", "questions": [{"q": "", "type": "single", "correct": [0], "options": [{"text": "vacuum the floor"}, {"text": "water the plants"}, {"text": "iron my T-shirt"}], "image": "https://classroom.wowteach.ru/media/gg3/u1/vacuum_room.webp"}, {"q": "", "type": "single", "correct": [1], "options": [{"text": "clear the table"}, {"text": "empty the dishwasher"}, {"text": "cook lunch"}], "image": "https://classroom.wowteach.ru/media/gg3/u1/empty_dishwasher.webp"}, {"q": "", "type": "single", "correct": [0], "options": [{"text": "feed the dog"}, {"text": "tidy my room"}, {"text": "wash the dishes"}], "image": "https://classroom.wowteach.ru/media/gg3/u1/feed_dog.webp"}, {"q": "", "type": "single", "correct": [2], "options": [{"text": "make my bed"}, {"text": "put away my clothes"}, {"text": "take out the rubbish"}], "image": "https://classroom.wowteach.ru/media/gg3/u1/take_rubbish.webp"}, {"q": "", "type": "single", "correct": [1], "options": [{"text": "load the washing machine"}, {"text": "set the table"}, {"text": "water the plants"}], "image": "https://classroom.wowteach.ru/media/gg3/u1/set_table.webp"}, {"q": "", "type": "single", "correct": [2], "options": [{"text": "iron my T-shirt"}, {"text": "wash the dishes"}, {"text": "make my bed"}], "image": "https://classroom.wowteach.ru/media/gg3/u1/make_bed.webp"}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "Послушай запись и соедини имя с делом по дому", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/gg3%20wb/GG%20L3%20WkBk%20A3.mp3", "pairs": [{"left": "Fred", "right": "vacuum the floor"}, {"left": "Gary", "right": "feed the dog"}, {"left": "Arthur", "right": "take out the rubbish"}, {"left": "Nelly", "right": "set the table"}, {"left": "Walter", "right": "empty the dishwasher"}, {"left": "Mary", "right": "make my bed"}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Послушай запись ещё раз и выбери правильный вариант", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/gg3%20wb/GG%20L3%20WkBk%20A3.mp3", "questions": [{"q": "Fred tidies his room on …", "type": "single", "correct": [1], "options": [{"text": "Fridays"}, {"text": "Saturdays"}, {"text": "Sundays"}]}, {"q": "Gary ___ looks after his sister at the weekend.", "type": "single", "correct": [0], "options": [{"text": "sometimes"}, {"text": "never"}, {"text": "always"}]}, {"q": "Arthur helps at home after …", "type": "single", "correct": [2], "options": [{"text": "breakfast"}, {"text": "lunch"}, {"text": "dinner"}]}, {"q": "Nelly …", "type": "single", "correct": [1], "options": [{"text": "loads the dishwasher"}, {"text": "hasn’t got a dishwasher"}, {"text": "doesn’t like the dishwasher"}]}, {"q": "Walter ___ chores.", "type": "single", "correct": [1], "options": [{"text": "likes"}, {"text": "hates"}, {"text": "doesn’t do"}]}, {"q": "Mary does lots of chores …", "type": "single", "correct": [0], "options": [{"text": "every day"}, {"text": "at the weekend"}, {"text": "on Mondays"}]}]}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай текст и выбери подходящее слово", "mode": "choice", "text": "Ellen is my neighbour. In her family, the children and parents don't do a lot of things together on weekdays. They never have breakfast as a family __because__ her mum and dad leave for work early. The family don't have lunch together, __but__ they always eat dinner at home.\nOn Saturdays, Ellen does her chores. She tidies her bedroom __and__ she loads the washing machine. Amy, her sister, often helps her. Then they watch TV __and__ hang out with their friends. On Sundays, Ellen, Amy and their parents often go to the park. They don't have a car, __so__ they take a bus.", "choices": [["but"], ["so"], ["so"], ["because"], ["because"]]}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'task', $blk${"title": "Напиши о человеке, которого хорошо знаешь ✍️", "needs_review": true, "html": "<p>Выбери человека — друга, соседа, родственника — и напиши о нём 5–6 предложений. Ответь по порядку:</p><p>1 что он делает в будни;<br>2 какие дела по дому он делает в выходные;<br>3 что вы делаете вместе в выходные.</p><p>Свяжи предложения словами <b>and</b>, <b>but</b>, <b>because</b>, <b>so</b>.</p><p><i>Например: Andy is my cousin. He gets up at seven, so he always has breakfast at home.</i></p>"}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_star.webp\" alt=\"\" style=\"height:200px\"></p><p>Остался последний шаг — проверь себя.</p>"}$blk$::jsonb, 6);
end $$;

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = '96161506-701b-4074-9115-ee113b71a739' and title = 'Homework 7';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('96161506-701b-4074-9115-ee113b71a739', 'Homework 7', 6, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 6, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_girl_wave.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 1 · Проверь себя</h2><p>Повторяем весь юнит: слова о характере, дела по дому, два времени и просьбы о помощи.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай текст о семье Боба и перетащи слова в пропуски", "mode": "drag", "text": "Dad is cool, but he's bossy. He tells everybody what to do. But my sister never listens to him and she never tidies her room. She's very __messy__.\nGrandpa is lots of fun. He doesn't mind what we watch on TV or what we play. He's very __easy-going__.\nMy grandma likes planning everything because she's __organised__. She plans the best holidays and trips.\nI have a baby brother. He's not in the photo. He cries a lot and he makes a lot of noise. He's very __loud__!\nLuckily, Mum is __patient__ and she doesn't get angry."}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Записка мамы: выбери правильное слово", "questions": [{"q": "___ your beds.", "type": "single", "correct": [1], "options": [{"text": "Set"}, {"text": "Make"}]}, {"q": "___ your T-shirts.", "type": "single", "correct": [0], "options": [{"text": "Iron"}, {"text": "Vacuum"}]}, {"q": "Water the ___ in the garden.", "type": "single", "correct": [1], "options": [{"text": "dogs"}, {"text": "plants"}]}, {"q": "___ out the rubbish.", "type": "single", "correct": [1], "options": [{"text": "Hang"}, {"text": "Take"}]}, {"q": "___ the floor in the living room.", "type": "single", "correct": [1], "options": [{"text": "Load"}, {"text": "Vacuum"}]}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Выбери правильную форму глагола", "questions": [{"q": "I usually ___ a snack in the morning.", "type": "single", "correct": [0], "options": [{"text": "have"}, {"text": "am having"}]}, {"q": "He ___ his friend right now.", "type": "single", "correct": [1], "options": [{"text": "texts"}, {"text": "is texting"}]}, {"q": "She ___ this film!", "type": "single", "correct": [0], "options": [{"text": "loves"}, {"text": "is loving"}]}, {"q": "What ___ at the moment?", "type": "single", "correct": [1], "options": [{"text": "do you do"}, {"text": "are you doing"}]}, {"q": "Grandpa often ___ tennis at the weekend.", "type": "single", "correct": [0], "options": [{"text": "plays"}, {"text": "is playing"}]}]}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай телефонный разговор и выбери правильную форму", "mode": "choice", "text": "Andy: Are you doing your chores?\nBeth: No, __I'm not__. __I'm playing__ a new video game.\nAndy: Oh. Is Fred there?\nBeth: Yes. Do you want to speak to him?\nAndy: Yes, please.\nBeth: Just a minute. __He's tidying__ his room. Fred! It's Andy on the phone.\nFred: Hi, Andy.\nAndy: Hi. I'm with Bob and __we're watching__ TV, but it's boring. Do you want to go to the park with us?\nFred: Sure. __I'm not doing__ anything important right now. Let's meet in five minutes.", "choices": [["I don't", "I amn’t"], ["I play", "I playing"], ["He tidies", "He tidy"], ["we watch", "we watching"], ["I don't do", "I'm not do"]]}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Впиши по одному слову в каждый пропуск", "mode": "drag", "text": "A: Do you need __any__ help with the sofa?\nB: Yes, __please__.\nA: Can you help __me__ with the chair, please?\nB: Yes, of __course__.\nA: Can I help you with the lamp?\nB: No, that's __fine__, thank you."}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'speaking', $blk${"title": "Расскажи о делах по дому 🎤", "needs_review": true, "html": "<p>Расскажи, кто что делает у вас дома и что делаешь прямо сейчас ты. Скажи 4–5 предложений и используй оба времени.</p><p><i>Например: My brother usually waters the plants. Right now he is doing his homework.</i></p>"}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_certificate.webp\" alt=\"\" style=\"height:200px\"></p><p>Юнит 1 пройден. Дальше — тест юнита.</p>"}$blk$::jsonb, 7);
end $$;
